const QUESTIONS = [
  {
    id: "q1",
    question: "Which of the following are statically typed languages?",
    helpText: "Tip: Select all that apply. Static typing means types are checked at compile time.",
    choices: [
      { id: "a", label: "TypeScript" },
      { id: "b", label: "Python" },
      { id: "c", label: "Rust" },
      { id: "d", label: "JavaScript" },
    ],
    correct: ["a", "c"],
  },
  {
    id: "q2",
    question: "Which languages run natively in a web browser?",
    choices: [
      { id: "a", label: "JavaScript" },
      { id: "b", label: "WebAssembly" },
      { id: "c", label: "Ruby" },
      { id: "d", label: "Go" },
    ],
    correct: ["a", "b"],
  },
  {
    id: "q3",
    question: "Which of these languages support functional programming paradigms?",
    choices: [
      { id: "a", label: "Haskell" },
      { id: "b", label: "Elixir" },
      { id: "c", label: "COBOL" },
      { id: "d", label: "Scala" },
    ],
    correct: ["a", "b", "d"],
  },
];

function Choice({ name, choice, checked, onToggle }) {
  return (
    <label className={`choice${checked ? " selected" : ""}`}>
      <input
        type="checkbox"
        name={name}
        value={choice.id}
        checked={checked}
        onChange={() => onToggle(choice.id)}
      />
      <span className="choice-label">{choice.label}</span>
    </label>
  );
}

function Question({ index, data, selected, onToggle }) {
  return (
    <div className="form-field">
      <div className="question-header">
        <span className="question-number">Question {index + 1}</span>
      </div>
      <p className="question-text">{data.question}</p>
      {data.helpText && <p className="help-text">{data.helpText}</p>}
      <div className="choices" role="group" aria-label={data.question}>
        {data.choices.map((c) => (
          <Choice
            key={c.id}
            name={data.id}
            choice={c}
            checked={selected.includes(c.id)}
            onToggle={onToggle}
          />
        ))}
      </div>
    </div>
  );
}

function Results({ answers }) {
  let score = 0;
  QUESTIONS.forEach((q) => {
    const sel = (answers[q.id] || []).slice().sort().join(",");
    const correct = q.correct.slice().sort().join(",");
    if (sel === correct) score += 1;
  });
  return (
    <div className="results">
      <h2>Results</h2>
      <p className="score">{score} / {QUESTIONS.length}</p>
      <p>Thanks for taking the quiz!</p>
    </div>
  );
}

function App() {
  const [answers, setAnswers] = useState(
    Object.fromEntries(QUESTIONS.map((q) => [q.id, []]))
  );
  const [submitted, setSubmitted] = useState(false);

  const toggle = (qid) => (cid) => {
    setSubmitted(false);
    setAnswers((prev) => {
      const cur = prev[qid];
      const next = cur.includes(cid)
        ? cur.filter((x) => x !== cid)
        : [...cur, cid];
      return { ...prev, [qid]: next };
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>Computer Languages Quiz</h1>
        <p>Three questions · Multiple answers allowed per question</p>
      </header>
      <form className="quiz-form" onSubmit={handleSubmit}>
        {QUESTIONS.map((q, i) => (
          <Question
            key={q.id}
            index={i}
            data={q}
            selected={answers[q.id]}
            onToggle={toggle(q.id)}
          />
        ))}
        <button type="submit" className="submit-btn">Submit Answers</button>
        {submitted && <Results answers={answers} />}
      </form>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
